'use strict';
const {CARDS,SUITS,ZODIAC,PLANETS,SOURCES}=window.TAROT;
const $=(s,root=document)=>root.querySelector(s);
const $$=(s,root=document)=>[...root.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const ICONS={book:'<path d="M12 5c-3-2-7-2-10-1v15c4-1 7-1 10 1 3-2 6-2 10-1V4c-3-1-7-1-10 1Z"/><path d="M12 5v15"/>',spark:'<path d="m12 2 2.6 7.4L22 12l-7.4 2.6L12 22l-2.6-7.4L2 12l7.4-2.6Z"/>',bookmark:'<path d="M6 3h12v18l-6-4-6 4Z"/>',pen:'<path d="m14 4 6 6M4 20l5-1L21 7a2 2 0 0 0-4-4L5 15Z"/><path d="M4 20h16"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',grid:'<rect x="3" y="3" width="6" height="6" rx="1"/><rect x="15" y="3" width="6" height="6" rx="1"/><rect x="3" y="15" width="6" height="6" rx="1"/><rect x="15" y="15" width="6" height="6" rx="1"/>',list:'<path d="M8 5h13M8 12h13M8 19h13M3 5h1M3 12h1M3 19h1"/>',close:'<path d="m5 5 14 14M19 5 5 19"/>',left:'<path d="m15 5-7 7 7 7"/>',right:'<path d="m9 5 7 7-7 7"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',upload:'<path d="M12 15V3m-5 5 5-5 5 5M4 17v4h16v-4"/>',check:'<path d="m4 12 5 5L20 6"/>'};
const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[name]||ICONS.spark}</svg>`;
$$('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));
const STORE='tarot-agents-homework-v1';
const validIds=new Set(CARDS.map(c=>c.id));
let storageAvailable=true, stored={};
try{stored=JSON.parse(localStorage.getItem(STORE)||'{}');if(!stored||typeof stored!=='object')stored={};}catch{storageAvailable=false;}
function validEntry(e){return e&&typeof e.id==='string'&&typeof e.date==='string'&&!Number.isNaN(Date.parse(e.date))&&typeof e.text==='string'&&typeof e.question==='string'&&Array.isArray(e.cards)&&e.cards.length>0&&e.cards.length<=3&&e.cards.every(c=>validIds.has(c.id)&&typeof c.reversed==='boolean');}
const state={view:'library',category:'全部',query:'',layout:'grid',favorites:new Set(Array.isArray(stored.favorites)?stored.favorites.filter(id=>validIds.has(id)):[]),entries:Array.isArray(stored.entries)?stored.entries.filter(validEntry):[],notes:stored.notes&&typeof stored.notes==='object'&&!Array.isArray(stored.notes)?stored.notes:{},pool:'all',spread:1,allowReversed:true,question:'',reading:null,readingSaved:false,detailId:null,reversed:false,detailTab:'overview',editing:null,astroSection:'zodiac',selectedSign:'牡羊座'};
let toastTimer, deferredInstall;
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function persist(){try{localStorage.setItem(STORE,JSON.stringify({version:1,favorites:[...state.favorites],entries:state.entries,notes:state.notes}));storageAvailable=true;updateCounts();return true;}catch{storageAvailable=false;toast('此瀏覽器無法儲存資料，請匯出備份後再離開。');return false;}}
function updateCounts(){$('#favorite-count').textContent=state.favorites.size;$('#journal-count').textContent=state.entries.length;}
function sourceURL(c){if(c.suit==='major')return 'https://commons.wikimedia.org/wiki/Category:Rider-Waite-Smith_tarot_deck_(TaionWC)';return 'https://commons.wikimedia.org/wiki/File:'+(c.suit==='pentacles'?'Pents':c.suit[0].toUpperCase()+c.suit.slice(1))+String(c.number).padStart(2,'0')+'.jpg';}
const labels={library:'牌義圖書館',practice:'抽牌練習',favorites:'我的收藏',journal:'學習筆記',astrology:'星象指南'};
function navigate(view){if(!labels[view])view='library';state.view=view;state.query='';state.category='全部';state.editing=null;if(location.hash!=='#'+view)history.replaceState(null,'','#'+view);render();window.scrollTo({top:0,behavior:'instant'});}
function render(){document.body.classList.toggle('practice-page',state.view==='practice');updateCounts();$$('[data-view]').forEach(b=>{const active=b.dataset.view===state.view;b.classList.toggle('active',active);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});$('#breadcrumb-title').textContent=labels[state.view];document.title=labels[state.view]+' · 魔法師的學徒';if(state.view==='library'||state.view==='favorites')renderLibrary();else if(state.view==='practice')renderPractice();else if(state.view==='astrology')renderAstrology();else renderJournal();}
function intro(eyebrow,title,subtitle,extra='',className=''){return `<div class="page-intro ${className}"><div><h1>${title}</h1><p>${subtitle}</p></div>${extra}</div>`;}
const cats=['全部','大阿爾克那','權杖','聖杯','寶劍','錢幣','宮廷牌'];
function renderLibrary(){const saved=state.view==='favorites';$('#main').innerHTML=(saved?intro(saved?'YOUR PERSONAL COLLECTION':'A LITTLE WONDER, EVERY DAY',saved?'我的收藏':'牌義圖書館',saved?'把有共鳴的牌留下，慢慢讀懂它們。':'從一張牌開始，練習看見更多可能。',`<span class="edition"><i></i> 偉特塔羅・經典圖像</span>`):'')+`<div class="category-tabs" aria-label="牌卡分類">${cats.map(cat=>{let n=CARDS.filter(c=>(cat==='全部'||c.category===cat)&&(!saved||state.favorites.has(c.id))).length;return `<button class="category-tab" data-category="${cat}" aria-pressed="${state.category===cat}">${cat}<small>${n}</small></button>`;}).join('')}</div><div class="toolbar"><label class="search">${icon('search')}<span class="visually-hidden">搜尋牌名或關鍵詞</span><input id="card-search" type="search" placeholder="搜尋牌名、關鍵詞或星座…" autocomplete="off" value="${esc(state.query)}"></label><span class="result-count" id="result-count" aria-live="polite"></span><div class="view-toggle" aria-label="顯示方式"><button data-layout="grid" aria-label="圖庫檢視" aria-pressed="${state.layout==='grid'}">${icon('grid')}</button><button data-layout="list" aria-label="清單檢視" aria-pressed="${state.layout==='list'}">${icon('list')}</button></div></div><div id="card-grid" class="card-grid ${state.layout==='list'?'list-view':''}"></div>`;renderCards();}
function filteredCards(){const q=state.query.trim().toLowerCase();return CARDS.filter(c=>(state.category==='全部'||c.category===state.category)&&(state.view!=='favorites'||state.favorites.has(c.id))&&(!q||c.search.includes(q)));}
function tile(c){const saved=state.favorites.has(c.id);return `<article class="tarot-tile"><button class="card-open" data-card="${c.id}" aria-label="查看${c.name}牌義"><div class="card-frame"><img src="${c.image}" alt="${c.name}偉特原版牌面" loading="lazy" width="1108" height="1920"></div><div class="tile-info"><div class="tile-meta"><span class="tile-code">${c.code}</span><h3 class="tile-name">${c.name}</h3></div></div><p class="list-summary">${c.meaning}</p></button><button class="tile-bookmark ${saved?'saved':''}" data-favorite="${c.id}" aria-label="${saved?'取消收藏':'收藏'}${c.name}" aria-pressed="${saved}">${icon('bookmark')}</button></article>`;}
function empty(title,text,action,label){return `<div class="empty"><div class="empty-icon">✧</div><h2>${title}</h2><p>${text}</p>${action?`<button class="primary" data-action="${action}">${label}</button>`:''}</div>`;}
function renderCards(){const cards=filteredCards();$('#result-count').textContent=`${cards.length} 張牌`;$('#card-grid').innerHTML=cards.length?cards.map(tile).join(''):state.view==='favorites'&&state.favorites.size===0?empty('讓有共鳴的牌，留在身邊','點選牌面右上角的書籤，就能加入收藏。','to-library','去探索牌義'):empty('還沒找到這張牌','試試別的牌名或關鍵詞，也可以切回全部分類。','reset-filter','清除篩選');}
function toggleFavorite(id){if(state.favorites.has(id))state.favorites.delete(id);else state.favorites.add(id);const ok=persist();if(state.view==='favorites')renderLibrary();else if(state.view==='library')renderCards();else if(state.view==='astrology'&&state.astroSection==='zodiac')renderAstroSelection();if($('#card-dialog').open){const b=$('.detail-favorite');if(b){b.classList.toggle('saved',state.favorites.has(id));b.setAttribute('aria-pressed',state.favorites.has(id));b.innerHTML=icon('bookmark')+(state.favorites.has(id)?'已收藏':'收藏');}}if(ok)toast(state.favorites.has(id)?'已加入我的收藏':'已取消收藏');}
function captureCardDraft(){const editor=$('#card-note');if($('#card-dialog').open&&editor&&state.detailId)state.notes[state.detailId]=editor.value;}
function openCard(id,reversed=false){if(!validIds.has(id))return;captureCardDraft();state.detailId=id;state.reversed=reversed;state.detailTab='overview';renderDetail();if(!$('#card-dialog').open)$('#card-dialog').showModal();}
function renderDetail(){const c=CARDS.find(c=>c.id===state.detailId);const saved=state.favorites.has(c.id);$('#card-dialog').innerHTML=`<div class="detail-header"><span>牌義手冊 &nbsp;/&nbsp; ${c.category}${c.category==='宮廷牌'?'・'+SUITS[c.suit].name:''}</span><div class="detail-header-actions"><button class="icon-button" data-detail-step="-1" aria-label="上一張牌">${icon('left')}</button><button class="icon-button" data-detail-step="1" aria-label="下一張牌">${icon('right')}</button><button class="icon-button" data-close="card-dialog" aria-label="關閉牌義">${icon('close')}</button></div></div><div class="detail-body"><div class="detail-art"><button class="detail-flip" data-action="flip-card" aria-label="翻轉${c.name}牌面" aria-pressed="${state.reversed}"><img class="detail-image ${state.reversed?'reversed-image':''}" src="${c.image}" alt="${c.name}${state.reversed?'逆位':'正位'}牌面"></button><span class="flip-hint">輕點牌面，切換正逆位</span><div class="orientation" aria-label="牌面方向"><button data-orientation="upright" aria-pressed="${!state.reversed}">正位</button><button data-orientation="reversed" aria-pressed="${state.reversed}">逆位</button></div><p class="source-caption">偉特原版圖像 · <a href="${sourceURL(c)}" target="_blank" rel="noopener noreferrer">查看來源 ↗</a></p></div><div class="detail-content"><div class="eyebrow">${esc(c.element)} &nbsp;·&nbsp; ${c.category}</div><div class="detail-title-row"><div><h2 id="detail-title">${c.name}</h2></div><button class="detail-favorite ${saved?'saved':''}" data-detail-favorite="${c.id}" aria-pressed="${saved}">${icon('bookmark')}${saved?'已收藏':'收藏'}</button></div><div id="detail-summary" aria-live="polite">${detailSummary(c)}</div><div class="detail-tabs" role="tablist" aria-label="牌義內容">${[['overview','牌義速查'],['story','圖像故事'],['astrology','星象對應'],['inquiry','提問練習']].map(([id,name])=>`<button role="tab" id="tab-${id}" aria-controls="detail-panel" tabindex="${id===state.detailTab?'0':'-1'}" data-detail-tab="${id}" aria-selected="${id===state.detailTab}">${name}</button>`).join('')}</div><div id="detail-panel" role="tabpanel" aria-labelledby="tab-${state.detailTab}">${detailPanel(c)}</div><div class="note-editor"><label class="field-label" for="card-note">這張牌，讓你想到了什麼？</label><textarea id="card-note" maxlength="10000" placeholder="寫下圖像觀察、生活聯想，或今天的新發現…">${esc(state.notes[c.id]||'')}</textarea><div class="note-actions"><span>個人心得只保留在此裝置</span><button class="primary" data-action="save-card-note">${icon('pen')} 存入學習筆記</button></div></div></div></div>`;}
function detailPanel(c){if(state.detailTab==='story')return storyPanel(c);if(state.detailTab==='astrology')return astrologyPanel(c);if(state.detailTab==='inquiry')return `<p class="reverse-note">以下是提問線索，不是確定的人物、地點或日期預測。</p><table class="meaning-table"><tbody><tr><th>誰</th><td>${c.who}</td></tr><tr><th>什麼</th><td>${(state.reversed?c.reversed:c.keywords).join('、')}，如何對應眼前的事件？</td></tr><tr><th>何時</th><td>${c.when}。牌面不提供固定時間。</td></tr><tr><th>何處</th><td>${c.where}</td></tr><tr><th>為何</th><td>${c.meaning}</td></tr><tr><th>如何</th><td>${c.advice}</td></tr></tbody></table>`;if(state.detailTab==='reflection')return `<div class="symbol-box"><div class="section-label">01 &nbsp; 先看見，再解讀</div><p>觀察「${c.symbol}」。你最先注意到哪一個細節？人物朝向、顏色和距離帶給你什麼感覺？</p></div><div class="symbol-box"><div class="section-label">02 &nbsp; 把牌連回生活</div><p>你最近在什麼情境中感受到「${c.keywords[0]}」？如果這張牌是一個提醒，你想對自己說什麼？</p></div><div class="advice"><strong>03 &nbsp; 今天的一小步</strong>${c.advice}</div>`;return `<div class="symbol-box"><div class="section-label">圖像線索 · 看圖說故事</div><p>${c.symbol}</p></div>${state.reversed?'<p class="reverse-note">下列情境提示以核心牌義為起點；逆位時可追問：哪裡受阻、過度，或需要重新調整？</p>':''}<table class="meaning-table"><tbody><tr><th>感情</th><td>${c.love}</td></tr><tr><th>工作</th><td>${c.work}</td></tr><tr><th>學業</th><td>${c.study}</td></tr></tbody></table><div class="advice"><strong>給學徒的一句話</strong>${c.advice}</div>`;}

function detailSummary(c){return '<div class="tags '+(state.reversed?'reversed-tags':'')+'">'+(state.reversed?c.reversed:c.keywords).map(t=>'<span class="tag">'+esc(t)+'</span>').join('')+'</div><p class="meaning-copy">'+(state.reversed?'逆位時，留意「'+c.reversed.join('、')+'」。這股能量可能受阻、過度，或正在轉向內在。':c.meaning)+'</p>';}
function setOrientation(reversed){
  if(state.reversed===reversed)return;
  captureCardDraft();state.reversed=reversed;
  const c=CARDS.find(c=>c.id===state.detailId),image=$('.detail-image');
  image.classList.toggle('reversed-image',reversed);image.alt=c.name+(reversed?'逆位':'正位')+'牌面';
  $('.detail-flip').setAttribute('aria-pressed',String(reversed));
  $$('[data-orientation]').forEach(b=>b.setAttribute('aria-pressed',String((b.dataset.orientation==='reversed')===reversed)));
  $('#detail-summary').innerHTML=detailSummary(c);$('#detail-panel').innerHTML=detailPanel(c);
}
function setDetailTab(tab){
  if(!['overview','story','astrology','inquiry'].includes(tab))return;
  state.detailTab=tab;
  $$('[data-detail-tab]').forEach(b=>{const selected=b.dataset.detailTab===tab;b.setAttribute('aria-selected',String(selected));b.tabIndex=selected?0:-1;});
  $('#detail-panel').innerHTML=detailPanel(CARDS.find(c=>c.id===state.detailId));$('#detail-panel').setAttribute('aria-labelledby','tab-'+tab);
  $('[data-detail-tab="'+tab+'"]').focus();
}
function sourceLink(url,label){return '<a href="'+url+'" target="_blank" rel="noopener noreferrer">'+label+' ↗</a>';}
function storyPanel(c){return '<div class="story-scene"><span class="section-label">畫面在說什麼</span><p>'+c.lore.scene+'</p></div><h3 class="panel-heading">細節慢慢看</h3><div class="symbol-details">'+c.lore.details.map((line,i)=>{const [title,text]=line.split('｜');return '<section><span class="detail-dot">'+(i+1)+'</span><div><h4>'+title+'</h4><p>'+text+'</p></div></section>';}).join('')+'</div><p class="interpretation-note">以上是圖像觀察與閱讀聯想，不是唯一的象徵定義。</p><details class="history-block" open><summary>這張牌的來處</summary><p>'+c.lore.history+'</p><p>1909 年，帕梅拉・科爾曼・史密斯受偉特委託繪製牌組。你看到的是這套圖像傳統的原版掃描。</p><div class="source-links">'+sourceLink(c.lore.source,'偉特圖解原文')+sourceLink(SOURCES.history,'繪者與創作背景')+(c.category==='宮廷牌'||c.suit!=='major'?sourceLink(SOURCES.early,'早期塔羅結構'):'')+'</div></details>';}
function astrologyPanel(c){const a=c.astro;const sign=ZODIAC.find(z=>z.name===a.sign),planet=PLANETS.find(p=>p.name===a.planet);return '<div class="astro-card-heading"><span class="astro-glyph">'+(sign?.glyph||planet?.glyph||{火:'△',水:'▽',風:'◇',土:'□'}[a.element]||'✧')+'</span><div><span class="section-label">'+(a.kind==='decan'?'行星與星座':a.kind==='zodiac'?'星座對應':a.kind==='planet'?'行星對應':'元素對應')+'</span><h3>'+a.name+(a.kind==='element'?'元素':'')+'</h3></div></div><p class="astro-meaning">'+a.meaning+'</p><dl class="astro-facts">'+(a.sign?'<div><dt>星座</dt><dd>'+a.sign+'</dd></div>':'')+(a.planet?'<div><dt>'+(a.kind==='decan'?'十度區間主星':'行星')+'</dt><dd>'+a.planet+'</dd></div>':'')+(a.element?'<div><dt>元素</dt><dd>'+a.element+'</dd></div>':'')+(a.decan?'<div><dt>黃道區間</dt><dd>第 '+a.decan+' 區間・'+a.degrees+'</dd></div>':'')+'</dl>'+(a.decan?'<p class="interpretation-note">每個星座的 30° 分成三個十度區間；這裡的主星是區間主星，不一定等於整個星座的守護星。</p>':'')+'<div class="astro-system">採黃金黎明傳統對應；不同牌系可能不同。這是象徵閱讀工具，不是個人星盤或即時星象。</div><div class="source-links">'+sourceLink(SOURCES.astrology,'傳統對應原表')+'</div><button class="secondary astro-guide-link" data-action="to-astrology">探索十二星座 '+icon('arrow')+'</button>';}
function renderAstrology(){
 $('#main').innerHTML=intro('','星象指南','把行星、星座與牌面，連成另一種理解。')+'<div class="astro-intro"><span>✧</span><p>行星看「什麼力量」，星座看「如何表現」，元素看「從哪裡著手」。<br>本手冊採黃金黎明塔羅對應與古典守護星，方便你在同一套系統中學習。</p></div><div class="category-tabs" aria-label="星象主題">'+[['zodiac','十二星座'],['planets','七曜行星'],['elements','四種元素']].map(([id,label])=>'<button class="category-tab" data-astro-section="'+id+'" aria-pressed="'+(state.astroSection===id)+'">'+label+'</button>').join('')+'</div><div id="astro-content"></div><p class="astro-footnote">象徵對應不代表命定性格或事件預測。太陽與月亮在占星的「七曜」中一併討論；此處不混用現代外行星守護。 '+sourceLink(SOURCES.astrology,'對應資料來源')+'</p>';
 if(state.astroSection==='zodiac'){$('#astro-content').innerHTML='<div class="zodiac-picker" aria-label="選擇星座">'+ZODIAC.map(z=>'<button data-sign="'+z.name+'" aria-pressed="'+(state.selectedSign===z.name)+'"><span>'+z.glyph+'</span>'+z.name+'</button>').join('')+'</div><section id="zodiac-detail" aria-live="polite"></section>';renderAstroSelection();}
 else if(state.astroSection==='planets')$('#astro-content').innerHTML='<div class="planet-grid">'+PLANETS.map(p=>'<article class="planet-card"><span class="astro-glyph">'+p.glyph+'</span><h2>'+p.name+'</h2><h3>'+p.theme+'</h3><p>'+p.meaning+'</p><button class="text-button" data-card="major_'+String(p.major).padStart(2,'0')+'">對應 '+CARDS[p.major].name+' ↗</button></article>').join('')+'</div>';
 else $('#astro-content').innerHTML='<div class="element-grid">'+Object.entries(SUITS).map(([id,s])=>'<article class="element-card"><span class="element-symbol">'+{火:'△',水:'▽',風:'◇',土:'□'}[s.element]+'</span><h2>'+s.element+'元素</h2><span class="tag">'+s.name+'</span><p>'+s.theme+'</p><p class="element-question">'+{火:'我想推動什麼？',水:'我真正感受到什麼？',風:'我需要釐清什麼？',土:'我能實際落實什麼？'}[s.element]+'</p><button class="text-button" data-card="'+id+'_01">從'+s.name+'王牌開始 ↗</button></article>').join('')+'</div>';
}
function renderAstroSelection(){const z=ZODIAC.find(s=>s.name===state.selectedSign);$$('[data-sign]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.sign===z.name)));const related=CARDS.filter(c=>c.astro.sign===z.name);$('#zodiac-detail').innerHTML='<div class="zodiac-summary"><div class="zodiac-title"><span>'+z.glyph+'</span><div><h2>'+z.name+'</h2><p>'+z.theme+'</p></div></div><div class="tags"><span class="tag">'+z.element+'象</span><span class="tag">'+z.mode+'</span><span class="tag">守護星・'+z.ruler+'</span></div><p>'+z.prompt+'</p></div><div class="library-heading"><h2>對應牌卡</h2><span>一張大牌與三張十度區間小牌</span></div><div class="card-grid astro-related">'+related.map(tile).join('')+'</div>';}

function saveCardNote(){captureCardDraft();const text=String(state.notes[state.detailId]||'').trim();if(!text){toast('先寫下一點觀察，再存入筆記。');$('#card-note').focus();return;}const c=CARDS.find(c=>c.id===state.detailId);const existing=state.entries.find(e=>e.kind==='card'&&e.cards[0].id===c.id);if(existing){existing.text=text;existing.date=new Date().toISOString();existing.cards[0].reversed=state.reversed;}else state.entries.unshift({id:makeId(),kind:'card',date:new Date().toISOString(),question:c.name+'・牌面觀察',cards:[{id:c.id,reversed:state.reversed}],text});state.entries.sort((a,b)=>new Date(b.date)-new Date(a.date));if(persist())toast('已存入學習筆記');if(state.view==='journal')renderJournal();}
function makeId(){return globalThis.crypto?.randomUUID?.()||'note-'+Date.now()+'-'+Math.random().toString(36).slice(2);}
function renderPractice(){$('#main').innerHTML=intro('A MOMENT TO LISTEN','抽牌練習','先觀察，再聯想。讓今天的牌，成為一個好問題。',`<span class="edition"><i></i> 靜下心，回到此刻</span>`)+`<div class="practice-layout"><div class="pool-selector" role="group" aria-label="選擇卡池"><button data-pool="all" aria-pressed="${state.pool==='all'}">全部</button><button data-pool="major" aria-pressed="${state.pool==='major'}">大牌</button><button data-pool="minor" aria-pressed="${state.pool==='minor'}">小牌</button></div><section class="reading-table" id="reading-table" aria-label="抽牌結果" aria-live="polite">${readingHTML()}</section><div class="practice-actions"><button class="primary" data-action="draw">${icon('spark')} 抽牌</button><button class="secondary" data-action="save-reading" ${!state.reading||state.readingSaved?'disabled':''}>${icon(state.readingSaved?'check':'pen')}${state.readingSaved?'已記錄':'記錄'}</button><button class="secondary" data-action="practice-settings">設定</button></div><dialog id="practice-settings" aria-label="抽牌設定"><button class="settings-close secondary" data-close="practice-settings">完成</button><section class="practice-form" aria-label="抽牌設定"><h2>留一點時間給自己</h2><p>想一個開放式問題。<br>例如：「面對今天的挑戰，我可以留意什麼？」</p><div class="question-group"><label class="field-label" for="reading-question">今天想探索的問題 <span>（選填）</span></label><textarea id="reading-question" rows="3" maxlength="300" placeholder="我想更了解…">${esc(state.question)}</textarea></div><div><span class="field-label">選擇牌陣</span><div class="spread-options"><button data-spread="1" aria-pressed="${state.spread===1}">單張指引</button><button data-spread="3" aria-pressed="${state.spread===3}">三張探索</button></div></div><label class="check-label"><input id="allow-reversed" type="checkbox" ${state.allowReversed?'checked':''}> 包含逆位牌</label><p class="practice-hint">${state.spread===3?'三張牌分別代表：現況、挑戰、建議。':'一張牌，一個值得留意的角度。'}<br>抽牌用於學習與自我反思。</p></section></dialog></div><section class="learn-tip"><h3>不是急著找答案，而是練習好好提問。</h3><p>先描述你看見的畫面，再想想它與問題的關係。你可以點開牌義作參考，最後記下自己的理解。每次回看，都可能發現新的線索。</p></section>`;}
function readingHTML(){if(!state.reading)return `<div class="deck-back" aria-hidden="true"><span>✧</span><small>魔法師的學徒</small></div><h2>你的下一個發現，正在這裡。</h2><p>深呼吸，想一個問題。<br>準備好了，就讓一張牌陪你開始。</p>`;return (state.reading.question?`<div class="reading-question">「${esc(state.reading.question)}」</div>`:'')+`<div class="reading-cards">${state.reading.cards.map((r,i)=>{const c=CARDS.find(c=>c.id===r.id);return `<article class="reading-card" style="animation-delay:${i*.1}s"><button data-card="${r.id}" data-reversed="${r.reversed}" aria-label="查看${c.name}${r.reversed?'逆位':'正位'}牌義"><img src="${c.image}" alt="${c.name}${r.reversed?'逆位':'正位'}" class="${r.reversed?'reversed-image':''}"><h3>${c.name}</h3></button></article>`;}).join('')}</div><div class="reading-reflection"><p>先說出三個畫面細節，再寫下它與你的問題有什麼連結。</p></div>`;}
function randomInt(max){if(globalThis.crypto?.getRandomValues){const a=new Uint32Array(1),limit=Math.floor(4294967296/max)*max;do{crypto.getRandomValues(a);}while(a[0]>=limit);return a[0]%max;}return Math.floor(Math.random()*max);}
function draw(){state.question=$('#reading-question').value.trim();state.allowReversed=$('#allow-reversed').checked;const deck=CARDS.filter(c=>state.pool==='all'||(state.pool==='major'?c.id.startsWith('major_'):!c.id.startsWith('major_')));for(let i=deck.length-1;i>0;i--){const j=randomInt(i+1);[deck[i],deck[j]]=[deck[j],deck[i]];}state.reading={question:state.question,date:new Date().toISOString(),cards:deck.slice(0,state.spread).map(c=>({id:c.id,reversed:state.allowReversed&&randomInt(2)===1}))};state.readingSaved=false;renderPractice();}
function saveReading(){if(!state.reading||state.readingSaved)return;const entry={...state.reading,id:makeId(),kind:'reading',text:'',question:state.reading.question||'今天，我可以留意什麼？'};state.entries.unshift(entry);if(persist()){state.readingSaved=true;navigate('journal');startEdit(entry.id);toast('抽牌已保存，寫下你自己的觀察吧。');}}
function renderJournal(){$('#main').innerHTML=intro('NOTES ALONG THE WAY','學習筆記','記下當下的理解，留給未來的自己。',`<div class="journal-tools"><button class="secondary" data-action="export">${icon('download')} 匯出備份</button><button class="secondary" data-action="import">${icon('upload')} 匯入備份</button><input type="file" id="import-file" accept=".json,application/json" hidden></div>`,'journal-page-intro')+`<div class="journal-notice">${storageAvailable?'筆記與收藏儲存在此瀏覽器，沒有上傳到雲端。':'目前瀏覽器儲存不可用，資料僅暫存在此頁面。'}更換裝置或清除瀏覽資料前，請先匯出備份。</div><div class="journal-list">${state.entries.length?state.entries.map(entryHTML).join(''):empty('第一頁，等你來寫','在牌義頁寫下觀察，或儲存一次抽牌練習。','start-practice','開始一段練習')}</div>`;}
function entryHTML(e){const editing=state.editing===e.id;return `<article class="journal-entry" data-entry="${esc(e.id)}"><div class="entry-images ${e.cards.length>1?'multiple':''}">${e.cards.map(r=>{const c=CARDS.find(c=>c.id===r.id);return `<button data-card="${r.id}" data-reversed="${r.reversed}" aria-label="查看${c.name}牌義" style="padding:0"><img src="${c.image}" alt="${c.name}" loading="lazy" style="${r.reversed?'transform:rotate(180deg)':''}"></button>`;}).join('')}</div><div class="entry-content"><div class="entry-date">${new Date(e.date).toLocaleString('zh-TW',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false})} &nbsp;·&nbsp; ${e.kind==='card'?'牌面觀察':'抽牌練習'}</div><div class="entry-heading"><h2>${esc(e.question)}</h2><button class="entry-delete" data-delete-entry="${esc(e.id)}" aria-label="刪除這則筆記">刪除</button></div><div class="entry-cards">${e.cards.map(r=>CARDS.find(c=>c.id===r.id).name+'・'+(r.reversed?'逆位':'正位')).join(' ／ ')}</div>${editing?`<label class="field-label" for="journal-text">我的觀察與聯想</label><textarea id="journal-text" class="journal-edit" maxlength="10000" placeholder="我看見…這讓我想到…">${esc(e.text)}</textarea><div class="entry-actions"><button data-save-entry="${esc(e.id)}">儲存心得</button><button data-cancel-edit>取消</button></div>`:`<p class="entry-text">${esc(e.text||'還沒有寫下心得。當時的你，看見了什麼？')}</p><div class="entry-actions"><button data-edit-entry="${esc(e.id)}">${e.text?'編輯心得':'寫下心得'}</button></div>`}</div></article>`;}
function startEdit(id){state.editing=id;renderJournal();$('#journal-text')?.focus();}
function saveEntry(id){const e=state.entries.find(e=>e.id===id);if(!e)return;e.text=$('#journal-text').value.trim();if(e.kind==='card')state.notes[e.cards[0].id]=e.text;state.editing=null;if(persist())toast('心得已儲存');renderJournal();}
function deleteEntry(id){const e=state.entries.find(e=>e.id===id);if(!e)return;showInfo('刪除這則筆記？',`<p>「${esc(e.question)}」將從此裝置移除。這個操作無法復原。</p><div class="journal-tools"><button class="secondary" data-close="info-dialog">保留筆記</button><button class="primary" data-confirm-delete="${esc(id)}">確定刪除</button></div>`);}
function showInfo(title,html){$('#info-dialog').innerHTML=`<button class="icon-button info-close" data-close="info-dialog" aria-label="關閉">${icon('close')}</button><h2 id="info-title">${title}</h2>${html}`;if(!$('#info-dialog').open)$('#info-dialog').showModal();}
function about(){showInfo('關於這本手冊',`<p>這是一個陪你觀察、理解與練習的塔羅學習空間。78 張牌使用偉特塔羅原版圖像，依大阿爾克那、四個花色的數字牌與宮廷牌分類。</p><p>牌義內容為另行撰寫的學習筆記；分類與速查呈現參考 <a href="https://nes-tarot.com/tarot-cartomantic-meanings/" target="_blank" rel="noopener noreferrer">Nes’ Tarot 牌義速查簡表</a>，沒有複製該站完整文字。</p><p>圖像：Pamela Colman Smith，Rider–Waite–Smith（Pam-A）掃描系列，來源 <a href="https://commons.wikimedia.org/wiki/Category:Rider-Waite-Smith_tarot_deck_(TaionWC)" target="_blank" rel="noopener noreferrer">Wikimedia Commons / TaionWC</a>。保留原始構圖；部分為來源提供的 960px 版本。</p><p>收藏與筆記只存在此裝置的瀏覽器。可在「學習筆記」匯出及匯入備份。網頁首次開啟後會保留基本介面與已瀏覽的牌圖供離線使用。</p><button class="secondary" data-action="install-help">如何加入手機主畫面</button>`);}
function beginner(){showInfo('讀牌，從觀察開始',`<p><b>01　先看圖，暫時不看解答。</b><br>描述人物、動作、方向與物件。留意第一個吸引你的細節。</p><p><b>02　把關鍵詞放回你的問題。</b><br>例如「力量」不一定是用力，也可能是溫柔而堅定地表達界線。</p><p><b>03　寫下自己的理解。</b><br>牌義是參考，讓實際生活與你的觀察一起參與。逆位也可以是受阻、過量或內在化，並非一律相反。</p><p><b>04　先從一張牌開始。</b><br>每天用一個開放式問題練習，過一段時間再回看筆記。</p><button class="primary" data-action="beginner-practice">開始單張練習 ${icon('arrow')}</button>`);}
function exportData(){const payload={app:'magicians-apprentice',version:1,exportedAt:new Date().toISOString(),favorites:[...state.favorites],entries:state.entries,notes:state.notes};const url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='魔法師的學徒-備份-'+new Date().toLocaleDateString('sv-SE')+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('備份檔已準備下載');}
async function importData(file){if(!file)return;if(file.size>10*1024*1024){toast('檔案過大，請選擇 10MB 以內的備份。');return;}try{const d=JSON.parse((await file.text()).replace(/^\uFEFF/,''));if(d.app!=='magicians-apprentice'||d.version!==1||!Array.isArray(d.entries)||!Array.isArray(d.favorites)||!d.entries.every(validEntry)||!d.favorites.every(id=>validIds.has(id)))throw new Error('invalid');const ids=new Set(state.entries.map(e=>e.id));let count=0;for(const e of d.entries)if(!ids.has(e.id)){state.entries.push({...e,text:e.text.slice(0,10000),question:e.question.slice(0,300)});ids.add(e.id);count++;}d.favorites.forEach(id=>state.favorites.add(id));if(d.notes&&typeof d.notes==='object')for(const [id,text]of Object.entries(d.notes)){if(validIds.has(id)&&typeof text==='string'&&!state.notes[id])state.notes[id]=text.slice(0,10000);}state.entries.sort((a,b)=>new Date(b.date)-new Date(a.date));if(persist())toast(`已合併備份，新增 ${count} 則筆記。`);renderJournal();}catch{toast('無法讀取，請選擇由此 App 匯出的有效 JSON 備份。');}}
document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;if(b.dataset.view){navigate(b.dataset.view);return;}if(b.dataset.category){state.category=b.dataset.category;$$('[data-category]').forEach(x=>x.setAttribute('aria-pressed',x===b));renderCards();return;}if(b.dataset.layout){state.layout=b.dataset.layout;$$('[data-layout]').forEach(x=>x.setAttribute('aria-pressed',x===b));$('#card-grid').classList.toggle('list-view',state.layout==='list');return;}if(b.dataset.card){openCard(b.dataset.card,b.dataset.reversed==='true');return;}if(b.dataset.favorite||b.dataset.detailFavorite){toggleFavorite(b.dataset.favorite||b.dataset.detailFavorite);return;}if(b.dataset.close){if(b.dataset.close==='card-dialog'){captureCardDraft();persist();}$('#'+b.dataset.close).close();return;}if(b.dataset.orientation){setOrientation(b.dataset.orientation==='reversed');return;}if(b.dataset.detailTab){setDetailTab(b.dataset.detailTab);return;}if(b.dataset.detailStep){captureCardDraft();persist();const index=CARDS.findIndex(c=>c.id===state.detailId);openCard(CARDS[(index+Number(b.dataset.detailStep)+CARDS.length)%CARDS.length].id);return;}if(b.dataset.pool){state.question=$('#reading-question').value;state.allowReversed=$('#allow-reversed').checked;state.pool=b.dataset.pool;renderPractice();return;}if(b.dataset.spread){state.question=$('#reading-question').value;state.allowReversed=$('#allow-reversed').checked;state.spread=Number(b.dataset.spread);renderPractice();$('#practice-settings').showModal();return;}if(b.dataset.editEntry){startEdit(b.dataset.editEntry);return;}if(b.dataset.saveEntry){saveEntry(b.dataset.saveEntry);return;}if(b.hasAttribute('data-cancel-edit')){state.editing=null;renderJournal();return;}if(b.dataset.deleteEntry){deleteEntry(b.dataset.deleteEntry);return;}if(b.dataset.confirmDelete){const e=state.entries.find(x=>x.id===b.dataset.confirmDelete);state.entries=state.entries.filter(x=>x.id!==b.dataset.confirmDelete);if(e?.kind==='card')delete state.notes[e.cards[0].id];if(persist())toast('筆記已刪除');$('#info-dialog').close();renderJournal();return;}if(b.dataset.sign){state.selectedSign=b.dataset.sign;renderAstroSelection();return;}if(b.dataset.astroSection){state.astroSection=b.dataset.astroSection;renderAstrology();return;}const action=b.dataset.action;if(action==='practice-settings'){$('#practice-settings').showModal();return;}if(action==='flip-card'){setOrientation(!state.reversed);return;}if(action==='to-astrology'){if($('#card-dialog').open){captureCardDraft();persist();$('#card-dialog').close();}navigate('astrology');return;}if(action==='start-practice'||action==='beginner-practice'){if($('#info-dialog').open)$('#info-dialog').close();navigate('practice');}else if(action==='to-library')navigate('library');else if(action==='beginner')beginner();else if(action==='reset-filter'){state.category='全部';state.query='';renderLibrary();}else if(action==='save-card-note')saveCardNote();else if(action==='draw')draw();else if(action==='save-reading')saveReading();else if(action==='export')exportData();else if(action==='import')$('#import-file').click();else if(action==='install-help')showInfo('把手冊帶在身邊',`<p><b>iPhone / iPad</b><br>使用 Safari 開啟已部署的 App 網址，點「分享」→「加入主畫面」。</p><p><b>Android / 電腦 Chrome 或 Edge</b><br>開啟已部署的 HTTPS 網址，從瀏覽器選單選擇安裝應用程式或加入主畫面。支援安裝時，頁面右上角也會出現安裝按鈕。</p><p>請在手機開啟這個 App 的 HTTPS 網址，即可使用或加入主畫面。收藏與筆記在不同裝置之間以匯出／匯入備份轉移。</p>`);});
document.addEventListener('input',event=>{if(event.target.id==='card-search'){state.query=event.target.value;renderCards();}if(event.target.id==='reading-question')state.question=event.target.value;});
document.addEventListener('change',event=>{if(event.target.id==='import-file')importData(event.target.files[0]);if(event.target.id==='allow-reversed')state.allowReversed=event.target.checked;});
document.addEventListener('keydown',event=>{if(event.target.matches('[role="tab"]')&&['ArrowLeft','ArrowRight','Home','End'].includes(event.key)){event.preventDefault();const tabs=$$('[role="tab"]');let i=tabs.indexOf(event.target);i=event.key==='Home'?0:event.key==='End'?tabs.length-1:(i+(event.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[i].click();}});
$('#card-dialog').addEventListener('cancel',()=>{captureCardDraft();persist();});
for(const d of $$('dialog')){d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom){if(d.id==='card-dialog'){captureCardDraft();persist();}d.close();}}});}
$('#about-button').addEventListener('click',about);
$('#footer-about').addEventListener('click',about);
$('#today-label').textContent=new Date().toLocaleDateString('zh-TW',{month:'long',day:'numeric',weekday:'long'});
window.addEventListener('hashchange',()=>{const v=location.hash.slice(1);if(labels[v])navigate(v);});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstall=e;$('#install-button').hidden=false;});
$('#install-button').addEventListener('click',async()=>{if(deferredInstall){await deferredInstall.prompt();deferredInstall=null;$('#install-button').hidden=true;}});
if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js').catch(()=>{});
